<?phpfunction encode_passwd($plain,$key){   $cipher="";   $plain=filter($plain); //  $plain=check_length($plain);   $key=filter($key);  // $key=check_length($key);   for($i=0;$i<strlen($plain);$i=$i+strlen($key)){      $pblock=substr($plain,$i,strlen($key));        for($j=0;$j<strlen($pblock);$j++){         $p=substr($pblock,$j,1);         $k=substr($key,$j,1);         $p=decimal($p);         $k=decimal($k);         $c=($p+$k)%26;         $c=ascii_letter($c);         $cipher=$cipher.$c;      }   }   return $cipher;}function decode_passwd($plain,$key){   $cipher="";   $plain=filter($plain); //  $plain=check_length($plain);      $key=filter($key);  // $key=check_length($key);   for($i=0;$i<strlen($plain);$i=$i+strlen($key)){      $pblock=substr($plain,$i,strlen($key));            for($j=0;$j<strlen($pblock);$j++){         $p=substr($pblock,$j,1);         $k=substr($key,$j,1);         $p=decimal($p);         $k=decimal($k);         $c=($p-$k)%26;         if($c<0)$c=$c+26;         $c=ascii_letter($c);         $cipher=$cipher.$c;      }   }   return $cipher;}function filter($input_text){   // function to filter input text     $input_text=preg_replace("/\s/","",$input_text); // eliminate whitespace   $input_text=preg_replace("/\W/","",$input_text); // eliminate non-alphabet character   $input_text=strtolower($input_text); // replace uppercase to lowercase   return $input_text;}function decimal($letter){   // function to change ascii letter (a..z) to decimal value (0..25)   switch ($letter){	case "a": $decvalue=0;break;	case "b": $decvalue=1;break;	case "c": $decvalue=2;break;	case "d": $decvalue=3;break;	case "e": $decvalue=4;break;	case "f": $decvalue=5;break;	case "g": $decvalue=6;break;	case "h": $decvalue=7;break;	case "i": $decvalue=8;break;	case "j": $decvalue=9;break;	case "k": $decvalue=10;break;	case "l": $decvalue=11;break;	case "m": $decvalue=12;break;	case "n": $decvalue=13;break;	case "o": $decvalue=14;break;	case "p": $decvalue=15;break;	case "q": $decvalue=16;break;	case "r": $decvalue=17;break;	case "s": $decvalue=18;break;	case "t": $decvalue=19;break;	case "u": $decvalue=20;break;	case "v": $decvalue=21;break;	case "w": $decvalue=22;break;	case "x": $decvalue=23;break;	case "y": $decvalue=24;break;	case "z": $decvalue=25;break;	default: $decvalue=$letter+26;break;   }return $decvalue;}function ascii_letter($decvalue){   // function to change decimal value (0..25) to ascii letter (a..z)   switch($decvalue){	case 0:$letter="a";break;	case 1:$letter="b";break;	case 2:$letter="c";break;	case 3:$letter="d";break;	case 4:$letter="e";break;	case 5:$letter="f";break;	case 6:$letter="g";break;	case 7:$letter="h";break;	case 8:$letter="i";break;	case 9:$letter="j";break;	case 10:$letter="k";break;	case 11:$letter="l";break;	case 12:$letter="m";break;	case 13:$letter="n";break;	case 14:$letter="o";break;	case 15:$letter="p";break;	case 16:$letter="q";break;	case 17:$letter="r";break;	case 18:$letter="s";break;	case 19:$letter="t";break;	case 20:$letter="u";break;	case 21:$letter="v";break;	case 22:$letter="w";break;	case 23:$letter="x";break;	case 24:$letter="y";break;	case 25:$letter="z";break;	default:$letter=$decvalue-26;break;   }return $letter;}?>